    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        DefaultTableModel modelo = (DefaultTableModel) Descripcion_Table.getModel();
        while (modelo.getRowCount() > 0) {
            modelo.removeRow(0);
        }
        try
        {
            DefaultTableModel Tabla = (DefaultTableModel)Descripcion_Table.getModel();
            datos Objeto_Datos = new datos();

            Objeto_Datos.conectar();
            String SQL= "select * from accesorios;";
            ResultSet conjreg=Objeto_Datos.obtenerDatos(SQL);
            while(conjreg.next()){
                String[] Fila= {conjreg.getString(1), conjreg.getString(2), conjreg.getString(3),conjreg.getString(4),conjreg.getString(5)};
                Tabla.addRow(Fila);
            }

        } catch (SQLException ex)
        {
            Logger.getLogger(Accesorios.class.getName()).log(Level.SEVERE, null, ex);
        }
    }//GEN-LAST:event_jButton1ActionPerformed

